pub const Hash = u64;

pub fn board(color: Color, ptype: PieceType, sq: Square) Hash {
    const index = @as(usize, @intFromEnum(ptype) - 1) * 81 * 2 | @as(usize, @intFromEnum(color)) * 81 | @as(usize, sq.raw);
    return board_table[index];
}

pub fn hand(color: Color, ptype: PieceType, count: usize) Hash {
    const index = @as(usize, @intFromEnum(ptype) - 1) * 18 * 2 | @as(usize, @intFromEnum(color)) * 18 | @as(usize, count);
    assert(hand_table[index] != 0);
    return hand_table[index];
}

